#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=9
DOT=$(cd "$(dirname "$0")" && pwd)
ZT_NETWORK=b6ad79b0c8703cd4
ENV_FILE="$HOME/.config/restic/env"
BW_SERVER=https://vault.jacocanete.dev
export PATH="$HOME/.local/bin:$HOME/.local/share/fnm/node-versions/v24.0.1/installation/bin:$PATH"

banner "Rebuild home-dev from dotfiles + backup"

stage "Hostname"
say "Restic snapshots are filed under host 'home-dev'; restore filters on it."
if [[ $(hostname) != home-dev ]] && confirm "Set this VM's hostname to home-dev?"; then
  sudo hostnamectl set-hostname home-dev
fi
pause

stage "ZeroTier: join homelab-network"
sudo systemctl enable --now zerotier-one
sudo zerotier-cli join "$ZT_NETWORK" >/dev/null || true
say "This VM's ZeroTier node ID: $(sudo zerotier-cli info | awk '{print $3}')"
step "Open your ZTNet admin → homelab-network → Members."
step "Deauthorize or delete the OLD home-dev member (the dead VM)."
step "Authorize the NEW member above and assign it 10.121.16.20."
say "Waiting for the network to report OK…"
until sudo zerotier-cli listnetworks | grep -q "$ZT_NETWORK.* OK "; do sleep 5; done
ZT_IFACE=$(sudo zerotier-cli listnetworks | awk -v n="$ZT_NETWORK" '$3==n {print $8}')
say "Online on $ZT_IFACE."
pause

stage "Firewall: UFW and the DDEV router reconciler"
say "Applies the README's UFW policy on $ZT_IFACE. A mistake here can cut off SSH;"
say "recovery is 'ssh home-server-dev-recovery' then 'sudo ufw disable'."
if confirm "Apply the firewall now?"; then
  sudo ufw default deny incoming
  sudo ufw default allow outgoing
  sudo ufw default deny routed
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.18 comment 'desktop via ZTNet'
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.127 comment 'ProBook via ZTNet'
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.132 to 10.121.16.20 port 4096 proto tcp comment 'phone to OpenCode web'
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.132 to 10.121.16.20 port 53 proto udp comment 'phone dev.test DNS'
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.132 to 10.121.16.20 port 53 proto tcp comment 'phone dev.test DNS'
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.132 to 10.121.16.20 port 22 proto tcp comment 'phone SSH'
  sudo ufw allow in on "$ZT_IFACE" from 10.121.16.132 to 10.121.16.20 port 60000:61000 proto udp comment 'phone mosh'
  sudo ufw allow in on enp1s0 from 192.168.122.1 to any port 22 proto tcp comment 'libvirt host recovery SSH'
  sudo ufw route allow in on "$ZT_IFACE" from 10.121.16.18 comment 'desktop to containers'
  sudo ufw route allow in on "$ZT_IFACE" from 10.121.16.127 comment 'ProBook to containers'
  fw=$HOME/.local/share/home-dev/ddev-router-firewall
  sudo install -o root -g root -m 0640 "$HOME/.local/share/home-dev/ufw-after.rules" /etc/ufw/after.rules
  sudo install -d -o root -g root -m 0755 /usr/local/libexec/ddev-router-firewall
  sudo install -o root -g root -m 0755 "$fw/reconcile" "$fw/watch" /usr/local/libexec/ddev-router-firewall/
  sudo install -o root -g root -m 0755 "$fw/ufw-after.init" /etc/ufw/after.init
  sudo install -o root -g root -m 0644 "$fw"/*.service "$fw"/*.timer /etc/systemd/system/
  # UFW must be up first: the reconciler adds rules to UFW's ufw-after-input chain.
  sudo ufw --force enable
  sudo systemctl daemon-reload
  sudo systemctl enable --now ddev-router-firewall.service ddev-router-firewall-events.service ddev-router-firewall-reconcile.timer
  sudo ufw reload
  sudo ufw status verbose
fi
pause

stage "Private DNS: *.dev.test via dnsmasq"
sed "s/^interface=.*/interface=$ZT_IFACE/" "$HOME/.local/share/home-dev/dnsmasq-ddev-dev-test.conf" |
  sudo install -o root -g root -m 0644 /dev/stdin /etc/dnsmasq.d/ddev-dev-test.conf
sudo systemctl enable dnsmasq
sudo systemctl restart dnsmasq
if dig +short @10.121.16.20 anything.dev.test | grep -qx 10.121.16.20; then
  say "dnsmasq answers *.dev.test with 10.121.16.20."
else
  warn "dnsmasq did not answer; check: journalctl -u dnsmasq"
fi
pause

stage "New SSH keys (never restored from backup)"
mkdir -p ~/.ssh && chmod 700 ~/.ssh
for key in home-dev-github-ed25519:jacogagarincanete@gmail.com home-dev-work-github-ed25519:jcanete@digitalimpulse.com; do
  file=$HOME/.ssh/${key%%:*}
  [[ -f $file ]] || ssh-keygen -q -t ed25519 -N '' -C "${key#*:} home-dev" -f "$file"
  line="${key#*:} namespaces=\"git\" $(cut -d' ' -f1,2 "$file.pub")"
  grep -qF "$line" "$DOT/git/.config/git/allowed_signers" || echo "$line" >> "$DOT/git/.config/git/allowed_signers"
done
[[ -f ~/.ssh/home-dev-pantheon-rsa ]] || ssh-keygen -q -t rsa -b 4096 -N '' -C "home-dev pantheon" -f ~/.ssh/home-dev-pantheon-rsa
[[ -f ~/.ssh/dogtoothtactical-wpengine-ed25519 ]] || ssh-keygen -q -t ed25519 -N '' -C "home-dev wpengine" -f ~/.ssh/dogtoothtactical-wpengine-ed25519
say "Personal GitHub (signed in as jacocanete):"
open_url "https://github.com/settings/ssh/new"
step "Add this key TWICE: once as 'Authentication Key', once as 'Signing Key':"
note "$(cat ~/.ssh/home-dev-github-ed25519.pub)"
step "Delete the old home-dev keys from the list while you are there."
pause "Done with personal GitHub?"
say "Work GitHub (sign in as the work account; authorize SSO for the orgs):"
step "Same page, same two key types:"
note "$(cat ~/.ssh/home-dev-work-github-ed25519.pub)"
pause "Done with work GitHub?"
say "Pantheon: Dashboard → Personal settings → SSH keys → add:"
note "$(cat ~/.ssh/home-dev-pantheon-rsa.pub)"
say "WP Engine: User portal → Profile → SSH keys → add:"
note "$(cat ~/.ssh/dogtoothtactical-wpengine-ed25519.pub)"
note "New signers were appended to ~/dotfiles/git/.config/git/allowed_signers: commit that."
pause

stage "Bitwarden: fetch credentials"
say "Log in to Bitwarden in this terminal (email, master password, 2FA)."
# Self-hosted vault; bw only lets the server change while logged out.
[[ $(bw config server) == "$BW_SERVER" ]] || { bw logout >/dev/null 2>&1 || true; bw config server "$BW_SERVER" >/dev/null; }
if bw login --check >/dev/null 2>&1; then BW_SESSION=$(bw unlock --raw); else BW_SESSION=$(bw login --raw); fi
export BW_SESSION
bw sync >/dev/null
while IFS=$'\t' read -r note path <&3; do
  [[ -z $note || $note == \#* ]] && continue
  mkdir -p "$(dirname "$HOME/$path")"
  if (umask 077; bw get notes "$note" > "$HOME/$path.bw") 2>/dev/null; then
    mv "$HOME/$path.bw" "$HOME/$path"
    say "${GREEN}✓${RESET} ~/$path"
  else
    rm -f "$HOME/$path.bw"
    warn "no '$note' note in Bitwarden; ~/$path comes back from the backup instead"
  fi
done 3< "$DOT/secrets.list"
bw lock >/dev/null
grep -q '^RESTIC_REPOSITORY=' "$ENV_FILE" || { warn "the 'home-dev restic' note lacks RESTIC_REPOSITORY; fix it in Bitwarden and re-run"; exit 1; }
claude mcp get coolify >/dev/null 2>&1 || claude mcp add-json coolify -s user \
  "{\"type\":\"http\",\"url\":\"https://coolify.jacocanete.dev/mcp\",\"headersHelper\":\"$HOME/.config/coolify-mcp/headers.sh\"}"
pause

stage "Restore state from backup"
say "Restores ~/Sites, ~/Projects, app state, secrets, and every Docker volume, then"
say "starts Hindsight, 9router, Headroom, OpenCode Web, Zellij Web and the backup timer."
if confirm "Restore the latest snapshot now? It overwrites files in place."; then
  "$DOT/restore.sh"
fi
pause

stage "Verify"
ssh -o StrictHostKeyChecking=accept-new -T personalgit 2>&1 | head -1 || true
ssh -o StrictHostKeyChecking=accept-new -T workgit 2>&1 | head -1 || true
systemctl --user --no-pager --failed
docker ps --format '{{.Names}}'
step "Start the DDEV sites you need:  ddev start --all"
pause

stage "Clients: the VM's SSH host key changed"
say "Host keys are new (private keys are never restored). New fingerprints:"
for k in /etc/ssh/ssh_host_ed25519_key.pub /etc/ssh/ssh_host_ecdsa_key.pub; do note "$(ssh-keygen -lf "$k")"; done
step "On the desktop, ProBook and phone (Termius): forget the old key, e.g. ssh-keygen -R 10.121.16.20"
step "Update the two fingerprints in ~/dotfiles/README.md (Development VM network) and commit."
note "The DDEV CA and ZeroTier address are unchanged, so clients need nothing else."
pause

finish
